#include <iostream>
#include <iomanip>

int main() {
    double val1 = 12.34567;
    double val2 = 123.0;
    double largeVal = 232123434.357;

    // Default precision (significant digits)
    std::cout << std::setprecision(3) << val1 << " " << 9.34567 << "\n";

    // showpoint forces decimal and trailing zeros
    std::cout << std::setprecision(6) << std::showpoint << val2 << "\n";

    // fixed changes setprecision to digits after decimal point
    std::cout << std::fixed << std::setprecision(2) << largeVal << " " << val1 << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // Right justification (default behavior of setw)
    std::cout << std::right;
    std::cout << std::setw(8) << "Item" << std::setw(6) << "ID" << "\n";
    std::cout << std::setw(8) << "C++" << std::setw(6) << 101 << "\n";

    // Left justification
    std::cout << std::left;
    std::cout << std::setw(8) << "Java" << std::setw(6) << 102 << "\n";

    // setw overflow demonstration
    std::cout << std::setw(3) << "Programming" << "#" << std::setw(2) << 9999 << "\n";

    return 0;
}
